"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["71082"],{6662(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.nao_encontrado","status":404,"titulo":"Tipo de conceito n\xe3o encontrado"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.nao_encontrado","requisitos":[],"oQueAconteceu":["O `{id}` da rota n\xe3o corresponde a nenhum tipo de conceito cadastrado. A resposta vale para a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) e para a desativa\xe7\xe3o (`DELETE /api/configuracao/admin/tipos-conceito/{id}`).","O tipo de conceito nunca \xe9 removido, s\xf3 desativado, e a busca desta opera\xe7\xe3o encontra tamb\xe9m o tipo desativado: desativar de novo um tipo desativado responde sucesso, e a atualiza\xe7\xe3o de um tipo desativado \xe9 aceita e n\xe3o o reativa. Esta causa \xe9, portanto, exclusivamente de identificador inexistente. A leitura p\xfablica de um tipo (`GET /api/configuracao/tipos-conceito/{id}`) responde 404 tamb\xe9m para o tipo desativado, mas essa resposta n\xe3o usa este c\xf3digo.","Na atualiza\xe7\xe3o, a ordem \xe9 esta: primeiro a leitura do corpo, e o que n\xe3o desserializa \xe9 recusado com 400; depois a confer\xeancia de que o `id` do corpo \xe9 o da rota, e a diverg\xeancia \xe9 recusada com 400; em seguida a valida\xe7\xe3o do conte\xfado do corpo, que responde 422; s\xf3 ent\xe3o a busca do tipo, que responde esta recusa; e por \xfaltimo o conflito de concorr\xeancia. As duas recusas de 400 n\xe3o trazem c\xf3digo deste cadastro. Assim, com um `{id}` que n\xe3o existe, um corpo desserializ\xe1vel e ids iguais, mas conte\xfado inv\xe1lido, a resposta \xe9 a recusa do conte\xfado (por exemplo, [nome do tipo de conceito obrigat\xf3rio](/erros/uniplus.configuracao.tipo_conceito.nome_obrigatorio)); s\xf3 com o conte\xfado v\xe1lido a resposta \xe9 esta. Na desativa\xe7\xe3o n\xe3o h\xe1 corpo, e a busca vem primeiro."],"comoResolver":["Confira o identificador do tipo na listagem (`GET /api/configuracao/tipos-conceito`), que traz os tipos ativos. Se o tipo nunca foi cadastrado, cadastre-o (`POST /api/configuracao/admin/tipos-conceito`)."],"ondeAparece":["Atualiza\xe7\xe3o de um tipo de conceito, com identificador que n\xe3o resolve","Desativa\xe7\xe3o de um tipo de conceito, com identificador que n\xe3o resolve"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);